<script setup lang="ts">
import { Settings,UserRound,ShieldCheck,UsersRound,ReceiptText } from '@lucide/vue';import { usePage } from '@inertiajs/vue3';import { onBeforeUnmount,onMounted,provide,readonly,ref,watch } from 'vue';import Orders from '@/components/settings/OrdersDatabase.vue';export type SettingsSection='profile'|'security'|'member'|'orders';const KEY='techstore.settings.section';const items=[{key:'profile' as SettingsSection,title:'Thông tin cá nhân',description:'Hồ sơ',icon:UserRound},{key:'security' as SettingsSection,title:'Bảo mật',description:'Mật khẩu & bảo vệ',icon:ShieldCheck},{key:'member' as SettingsSection,title:'Thành viên',description:'Hạng & mã giảm giá',icon:UsersRound},{key:'orders' as SettingsSection,title:'Đơn hàng',description:'Lịch sử & hóa đơn',icon:ReceiptText}];const page=usePage();const valid=(v:string|null):v is SettingsSection=>!!v&&items.some(i=>i.key===v);const pathSection=()=>typeof window!=='undefined'&&window.location.pathname==='/settings/member'?'member':null;const urlSection=()=>typeof window==='undefined'?null:(()=>{const v=new URLSearchParams(window.location.search).get('section');return valid(v)?v:null})();const stored=()=>{if(typeof window==='undefined')return null;try{const v=sessionStorage.getItem(KEY);return valid(v)?v:null}catch{return null}};const activeSection=ref<SettingsSection>(pathSection()??urlSection()??stored()??'profile');provide('techstore-settings-section',readonly(activeSection));const persist=(s:SettingsSection)=>{if(typeof window!=='undefined')try{sessionStorage.setItem(KEY,s)}catch{};if(typeof document!=='undefined')document.body.dataset.techstoreSettingsSection=s};const sync=()=>{const s=pathSection()??urlSection()??(typeof window!=='undefined'&&valid(window.history.state?.settingsSection)?window.history.state.settingsSection:null)??stored()??'profile';activeSection.value=s;persist(s)};const select=(s:SettingsSection)=>{activeSection.value=s;persist(s);if(typeof window!=='undefined'){const u=new URL(window.location.href);u.pathname='/settings/profile';s==='profile'?u.searchParams.delete('section'):u.searchParams.set('section',s);window.history.pushState({...window.history.state,settingsSection:s},'',`${u.pathname}${u.search}${u.hash}`)}};watch(activeSection,s=>{const requested=pathSection()??urlSection()??stored();if(requested&&requested!==s){activeSection.value=requested;persist(requested)}});watch(()=>page.url,s=>{if(s)sync()});onMounted(()=>{sync();window.addEventListener('popstate',sync);window.setTimeout(sync,0)});onBeforeUnmount(()=>window.removeEventListener('popstate',sync));
</script>
<template><div class="settings-page-shell"><header class="settings-hero"><div class="settings-hero-icon"><Settings :size="22"/></div><div><span class="settings-eyebrow">QUẢN LÝ TÀI KHOẢN</span><h1>Tài khoản</h1><p>Quản lý hồ sơ, bảo mật, thành viên và lịch sử mua hàng.</p></div></header><nav class="settings-nav-modern" aria-label="Tài khoản"><div class="settings-nav-links"><button v-for="item in items" :key="item.key" type="button" class="settings-nav-link-modern" :class="{'is-active':activeSection===item.key}" @click="select(item.key)"><span class="settings-nav-link-icon"><component :is="item.icon" :size="18"/></span><span class="settings-nav-link-copy"><strong>{{item.title}}</strong><small>{{item.description}}</small></span></button></div></nav><main class="settings-page-content"><div v-show="activeSection!=='orders'" class="settings-slot-view"><slot/></div><div v-show="activeSection==='orders'" class="settings-orders-view"><Orders/></div></main></div></template>
<style>.settings-page-shell{width:min(100% - 32px,1220px);margin:0 auto;padding:30px 0 56px}.settings-hero{display:flex;align-items:center;gap:16px;margin-bottom:18px}.settings-hero-icon{display:grid;width:52px;height:52px;flex:0 0 52px;place-items:center;border:1px solid #dbeafe;border-radius:16px;color:#2563eb;background:linear-gradient(145deg,#eff6ff,#f5f3ff)}.settings-eyebrow{display:block;margin-bottom:4px;color:#2563eb;font-size:11px;font-weight:900;letter-spacing:.14em}.settings-hero h1{margin:0;color:#101828;font-size:clamp(1.65rem,3vw,2.15rem);font-weight:850}.settings-hero p{margin:5px 0 0;color:#667085;font-size:.84rem}.settings-nav-modern{margin:0 0 28px;padding:7px;border:1px solid #e4e7ec;border-radius:18px;background:#fff;box-shadow:0 12px 32px rgba(16,24,40,.055)}.settings-nav-links{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}.settings-nav-link-modern{display:flex;align-items:center;min-width:0;gap:10px;padding:11px 12px;border:1px solid transparent;border-radius:13px;color:#667085;background:#fff;text-align:left;cursor:pointer}.settings-nav-link-modern.is-active{color:#1d4ed8;border-color:#bfdbfe;background:linear-gradient(135deg,#eff6ff,#f5f3ff);box-shadow:0 7px 18px rgba(37,99,235,.08)}.settings-nav-link-icon{display:grid;width:38px;height:38px;flex:0 0 38px;place-items:center;border-radius:11px;background:#f8fafc}.settings-nav-link-modern.is-active .settings-nav-link-icon{color:#2563eb;background:#fff}.settings-nav-link-copy{display:block;min-width:0;flex:1}.settings-nav-link-copy strong,.settings-nav-link-copy small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.settings-nav-link-copy strong{font-size:.78rem;font-weight:800}.settings-nav-link-copy small{margin-top:2px;color:#98a2b3;font-size:.64rem}.settings-page-content{position:relative}.settings-slot-view,.settings-orders-view{width:100%}@media(max-width:900px){.settings-nav-links{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:575px){.settings-page-shell{width:min(100% - 20px,1220px);padding-top:18px}.settings-nav-links{grid-template-columns:1fr}}</style>
